function ApplicationIcon({icon,kind}: {icon?:string;kind:string}) {
 const [failed,setFailed]=useState(false);
 useEffect(()=>setFailed(false),[icon]);
 return icon&&!failed?<img className="application-icon" src={icon} alt="" onError={()=>setFailed(true)}/>:kind==='process'?<Terminal/>:<Laptop/>;
}
