 {deviceEditor&&<Modal title="Customize device" onClose={()=>setDeviceEditor(null)} error={deviceLabelError} footer={<><button onClick={()=>saveDeviceLabel(true)}>Reset label</button><button className="primary" form="device-label-form" type="submit">Save label</button></>}><form id="device-label-form" className="form" onSubmit={e=>{e.preventDefault();saveDeviceLabel();}}><p className="muted">{deviceEditor.id}</p><label>Name<input autoFocus maxLength={80} placeholder={deviceEditor.id} value={deviceEditor.label.name} onChange={e=>setDeviceEditor({...deviceEditor,label:{...deviceEditor.label,name:e.target.value}})}/></label><label>Color<input type="color" value={deviceEditor.label.color} onChange={e=>setDeviceEditor({...deviceEditor,label:{...deviceEditor.label,color:e.target.value}})}/></label><label>Icon<select value={deviceEditor.label.icon} onChange={e=>setDeviceEditor({...deviceEditor,label:{...deviceEditor.label,icon:e.target.value as DeviceIconName}})}><option value="auto">Automatic from captured traffic</option><option value="android">Android</option><option value="ios">iOS</option><option value="mac">Mac</option><option value="generic">Generic device</option></select></label><p className="hint">Labels are saved on this Mac for this IP address. Automatic icons use captured platform metadata; encrypted or unidentified traffic keeps a generic icon. Shared IP addresses may represent several devices.</p></form></Modal>}
 {modal==='settings'&&<Modal error={actionError} title="Proxy settings" onClose={()=>setModal(null)} footer={<button className="primary" disabled={busy||!Number.isInteger(proxyPort)||proxyPort<1024||proxyPort>65535} onClick={async()=>{if(await action('/api/settings','PUT',{tlsDomains:domains.split(/\s+/).filter(Boolean),listenHost:lanEnabled?'0.0.0.0':'127.0.0.1',proxyPort}))setModal(null);}}>Save settings</button>}><div className="form"><div className="setting-summary"><ShieldCheck/><div><strong>HTTPS inspection</strong><p>Only domains in this list are decrypted. Other HTTPS connections appear with destination metadata only. Enabling inspection interrupts existing encrypted connections for newly enabled domains. The client may reconnect automatically; an in-flight request may need to be retried. You do not need to restart the app.</p></div></div><label className="check"><input type="checkbox" checked={lanEnabled} onChange={e=>setLanEnabled(e.target.checked)}/>Allow devices on the local network</label><p className="muted">Required for physical devices and Android. Enables the proxy listener on all network interfaces; keep your Mac on a trusted network.</p><label>Proxy port<input type="number" min={1024} max={65535} value={proxyPort} onChange={e=>setProxyPort(Number(e.target.value))}/></label><label>TLS domain allowlist<textarea className="mono" rows={6} value={domains} onChange={e=>setDomains(e.target.value)} placeholder={'api.example.com\n*.example.com'}/><small>One domain per line. Install and trust the local certificate on each device.</small></label><dl><dt>Proxy port</dt><dd>{data.settings.proxyPort??'—'}</dd><dt>LAN addresses</dt><dd>{connection?.lanAddresses?.join(', ')||'Use this Mac’s network address'}</dd><dt>Backend</dt><dd>{connection?.baseUrl??'Connecting…'}</dd></dl><McpSettings/></div></Modal>}
 {labTab&&<LabPanel api={api} records={data.records} selectedId={selection??undefined} initialTab={labTab} preferencesRevision={data.productivity?.revision} currentView={{filter,scope:searchScope,mode:searchMode,protocols:quickProtocols,statuses:quickStatuses,device:deviceFilter,application:applicationFilter,library:kind}} onApplyView={applySavedView} onClose={()=>showTools(null)} onChanged={refresh} onSelect={id=>setSelection(id)}/>}
 {modal==='setup'&&<Modal error={actionError} title="Connect a device" onClose={()=>setModal(null)} footer={<button onClick={()=>setModal(null)}>Done</button>}><div className="form"><label>Platform<select value={platform} onChange={e=>{setPlatform(e.target.value);setSetupResult('');setSetupTarget(e.target.value==='mac'?'':e.target.value==='iosSimulator'?deviceInventory?.simulators?.find((item:any)=>item.state==='Booted')?.id??'':'');}}>{Object.entries(platformLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label>{platform==='mac'?<><p className="muted">Enable Mac capture to route apps that use the system HTTP/HTTPS proxy through Streamglass. Trusting the certificate alone does not enable capture.</p><p className="muted">{deviceInventory?.networkNotice??'Detecting active network…'}</p><button disabled={busy} onClick={()=>void refreshDevices()}>Refresh networks</button></>:platform!=='iosSimulator'&&<p className="muted">Route the device’s HTTP proxy through this Mac, then install and trust Streamglass’s local certificate for HTTPS inspection.</p>}{['iosDevice','androidDevice','androidEmulator'].includes(platform)&&data.settings.listenHost!=='0.0.0.0'&&<p className="error-text">LAN access is disabled. Enable local network access in Proxy settings before connecting a physical device or Android.</p>}{['mac','iosSimulator'].includes(platform)&&<><p role="status">Mac monitoring: {deviceInventory?.monitorEnabled?'enabled':'disabled'}{deviceInventory?.monitorOverride?` · override: ${deviceInventory.monitorOverride}`:deviceInventory?.activeNetworkId?` · ${deviceInventory.activeNetworkId}`:' · waiting for an active network'}.</p>{(!deviceInventory?.activeNetworkId||deviceInventory?.monitorOverride)&&<details><summary>Advanced network override</summary><p className="muted">Use this when a VPN or multiple default routes prevent automatic selection. Clear it to follow the active network.</p><label>Network service<select value={setupNetworkTarget} onChange={e=>setSetupNetworkTarget(e.target.value)}><option value="">Automatic active network</option>{deviceInventory?.networkServices?.map((d:any)=><option key={d.id} value={d.id}>{d.name}{d.interface?` (${d.interface})`:''}</option>)}</select></label></details>}</>}{platform==='iosSimulator'&&<>
 <p className="muted">Prepare capture once to trust the Mac and simulator certificates, start the proxy, and enable Mac monitoring that follows the active network automatically.</p>
 <p className="muted">{deviceInventory?.networkNotice??'Detecting active network…'}</p>
 <button disabled={busy} onClick={()=>void refreshDevices()}>Refresh simulators and networks</button>

 <div className="inline setup-actions"><button disabled={!window.streamglass||busy||!deviceInventory?.savedProxyTargets?.some((key:string)=>key.startsWith('mac:'))} onClick={()=>void deviceAction('mac-restore-proxy')}>Disable Mac capture</button></div>
 {selectedNetwork?.proxyEnabled&&!selectedNetwork.canRestore&&<p className="muted">This proxy has no saved settings to restore. Manage it in macOS Network settings.</p>}
 <p role="status" className="muted">{deviceInventory?.simulatorNotice??'Checking simulator tools…'}</p>
 <ol className="setup-steps"><li>Select a booted simulator and click Prepare simulator capture. Mac apps using the active network’s system proxy are also captured.</li><li>Add the API domains you need to the TLS allowlist.</li><li>Reload the simulator app or page to create new connections. If it still uses an earlier proxy configuration, relaunch that simulator app.</li></ol>
 </>}{platform==='androidEmulator'&&<p className="muted">Automatic emulator setup uses ADB. Your debug app must trust user certificates; certificate pinning can prevent inspection.</p>}{platform==='androidDevice'&&<p className="muted">Wi-Fi setup does not require ADB or USB debugging. Configure the proxy on your phone using the address below.</p>}<ProxyAddress key={platform} addresses={['mac','iosSimulator'].includes(platform)?['127.0.0.1']:connection?.lanAddresses??[]} port={data.settings.proxyPort??8080} local={['mac','iosSimulator'].includes(platform)}/>{!['mac','iosSimulator'].includes(platform)&&<ol className="setup-steps"><li>Start the proxy and connect both devices to the same network.</li><li>Enter the IP address and port shown above in the device’s HTTP proxy settings.</li><li>Open the certificate page shown by the backend and trust the certificate.</li><li>Add the API domains you need to the TLS allowlist.</li></ol>}{platform==='iosDevice'&&<p className="muted">iOS: Wi-Fi → network details → Configure Proxy → Manual. After installing the profile, enable full trust in Settings → General → About → Certificate Trust Settings.</p>}{platform==='androidDevice'&&<p className="muted">Android: edit your Wi-Fi network’s proxy. Apps must allow user certificates in their debug network security configuration; certificate pinning may prevent inspection.</p>}{['iosSimulator','androidEmulator'].includes(platform)&&<label>{platform==='iosSimulator'?'Simulator':'Android device'}<select value={setupTarget} onChange={e=>setSetupTarget(e.target.value)}><option value="">{'Select a device…'}</option>{(platform==='iosSimulator'?deviceInventory?.simulators:deviceInventory?.android)?.map((d:any)=><option key={d.id} value={d.id}>{d.name}{d.interface?` (${d.interface})`:''}{d.active?' · active network':''}{d.state?` · ${d.state}`:''}</option>)}</select></label>}<div className="inline setup-actions">{(platform==='mac'?['mac-enable-proxy','mac-trust-ca','mac-restore-proxy']:platform==='iosSimulator'?['simulator-prepare']:['iosDevice','androidDevice'].includes(platform)?[]:['android-enable-proxy','android-install-ca','android-restore-proxy']).map(actionName=><button key={actionName} disabled={!window.streamglass||busy||(!setupTarget&&!actionName.startsWith('mac-'))||(actionName==='simulator-prepare'&&(!selectedNetwork||!deviceInventory?.simulators?.some((item:any)=>item.id===setupTarget&&item.state==='Booted')))||(actionName==='mac-enable-proxy'&&deviceInventory?.monitorEnabled&&!deviceInventory?.monitorError&&setupNetworkTarget===(deviceInventory?.monitorOverride??'')&&selectedNetwork?.proxyEnabled&&data.settings.proxyRunning!==false)||(actionName==='mac-restore-proxy'&&!deviceInventory?.savedProxyTargets?.some((key:string)=>key.startsWith('mac:')))} onClick={()=>void deviceAction(actionName)}>{actionName==='simulator-prepare'?'Prepare simulator capture':actionName==='mac-enable-proxy'?'Enable Mac capture':actionName==='mac-restore-proxy'?'Disable Mac capture':actionName.includes('restore')?'Restore proxy':actionName.includes('enable')?'Enable proxy':actionName.includes('trust')?'Trust HTTPS certificate':'Install certificate'}</button>)}<button onClick={openSettings}>TLS allowlist</button></div>{platform==='androidDevice'&&<details className="optional-adb"><summary>Optional ADB helpers</summary><p className="muted">Only these automatic helpers require Android platform-tools and an authorized device with USB or wireless debugging enabled. Manual Wi-Fi setup above works without them.</p><label>ADB device<select value={setupTarget} onChange={e=>setSetupTarget(e.target.value)}><option value="">Select an authorized device…</option>{deviceInventory?.android?.map((d:any)=><option key={d.id} value={d.id}>{d.name}{d.state?` · ${d.state}`:''}</option>)}</select></label><div className="inline setup-actions">{['android-enable-proxy','android-install-ca','android-restore-proxy'].map(actionName=><button key={actionName} disabled={!window.streamglass||busy||!deviceInventory?.android?.some((d:any)=>d.id===setupTarget)} onClick={()=>void deviceAction(actionName)}>{actionName==='android-enable-proxy'?'Enable proxy':actionName==='android-install-ca'?'Install certificate':'Restore proxy'}</button>)}</div></details>}{platform==='iosSimulator'&&<details><summary>Certificate-only setup for a managed Mac</summary><p className="muted">Install certificates without changing the Mac network proxy. Ask IT to configure the proxy, or configure it inside your app.</p><button disabled={!window.streamglass||busy||!deviceInventory?.simulators?.some((item:any)=>item.id===setupTarget&&item.state==='Booted')} onClick={()=>void deviceAction('simulator-certificates')}>Install certificates only</button></details>}{platform==='mac'&&selectedNetwork?.proxyEnabled&&!selectedNetwork.canRestore&&<p className="muted">This proxy was configured outside this session; there are no saved settings to restore. Manage it in macOS Network settings.</p>}{platform==='mac'&&<p className="muted">For HTTPS bodies, trust the certificate and add the destination to the TLS allowlist. Reload the app or page after enabling capture. Apps that ignore the system proxy or use certificate pinning may require their own proxy settings.</p>}{platform!=='iosSimulator'&&<div className="cert-callout"><div><strong>Download the certificate</strong><span>With the proxy configured, open this address in the device's browser.</span></div><code>http://mitm.it</code><button onClick={()=>{void (window.streamglass?.copyText?window.streamglass.copyText('http://mitm.it'):navigator.clipboard.writeText('http://mitm.it')).catch?.(()=>{});}}>Copy</button></div>}{setupResult&&<pre className="setup-output">{setupResult}</pre>}<p className="hint">Mac monitoring is remembered across restarts. Quitting restores the Mac’s saved proxy settings; monitoring resumes next launch. Disable Mac capture restores settings and turns monitoring off. For a phone configured manually, disable its Wi-Fi proxy when Streamglass is closed.</p>{(deviceInventory?.monitorError||deviceInventory?.monitorRestoreError)&&<p className="error-text" role="alert">{deviceInventory.monitorError||deviceInventory.monitorRestoreError}</p>}</div></Modal>}
 {contextMenu&&<RecordContextMenu x={contextMenu.x} y={contextMenu.y} onClose={closeContextMenu} returnFocus={contextMenu.target}>
 <div className="context-url" title={contextMenu.record.url}>{contextMenu.record.method} {contextMenu.record.url}</div>
 {(contextMenu.record.kind==='tunnel'||contextMenu.record.isEncrypted)&&<p className="context-notice">Exports and rules require SSL inspection. This connection is encrypted.</p>}
 {['curl','request','response','sse'].map(format=><button role="menuitem" key={format} disabled={contextMenu.record.kind==='tunnel'||contextMenu.record.isEncrypted} onClick={()=>{void exportRecord(format,contextMenu.record);closeContextMenu();}}>Export {format==='curl'?'cURL':format==='sse'?'SSE stream':format}</button>)}
 <button role="menuitem" onClick={()=>{void action(`/api/records/${contextMenu.record.id}/pin`,'POST',{pinned:!contextMenu.record.pinned});closeContextMenu();}}>{contextMenu.record.pinned?'Unpin request':'Pin request'}</button>
 <div className="context-divider"/>
 <button role="menuitem" onClick={()=>{setSelection(contextMenu.record.id);showTools('Views & notes');closeContextMenu();}}>Note and highlight…</button>
 {['Compare','Replay','Create mock','Share'].map(name=><button key={name} role="menuitem" disabled={name!=='Compare'&&(contextMenu.record.kind==='tunnel'||contextMenu.record.isEncrypted)} onClick={()=>{setSelection(contextMenu.record.id);showTools(name);closeContextMenu();}}>{name==='Replay'?'Edit and resend…':name==='Create mock'?'Save as mock…':name==='Share'?'Redacted export…':'Compare captures…'}</button>)}
 <button role="menuitem" disabled={contextMenu.record.kind==='tunnel'||contextMenu.record.isEncrypted} onClick={()=>ruleFromRecord(contextMenu.record,false)}>Create breakpoint…</button>
 <button role="menuitem" disabled={contextMenu.record.kind==='tunnel'||contextMenu.record.isEncrypted} onClick={()=>ruleFromRecord(contextMenu.record,true)}>Create JavaScript rule…</button>
 {(contextMenu.record.kind==='tunnel'||contextMenu.record.isEncrypted)&&<button role="menuitem" disabled={busy||!contextMenu.record.host||inspectionEnabled(contextMenu.record.host??'',contextMenu.record.port,data.settings.tlsDomains??[])} onClick={()=>{void enableInspection(contextMenu.record.host!);closeContextMenu();}}>{inspectionEnabled(contextMenu.record.host??'',contextMenu.record.port,data.settings.tlsDomains??[])?'SSL inspection enabled':'Enable SSL inspection…'}</button>}
 </RecordContextMenu>}

